<?php
$catalogRows=module_catalog();$bindings=[];
if($edit['id'])foreach(all('SELECT b.*,m.active FROM shop_product_module_bindings b JOIN shop_product_modules m ON m.id=b.module_id WHERE m.product_id=?',[$edit['id']]) as $binding)$bindings[(int)$binding['catalog_id']]=$binding;
$configEnabled=$_SERVER['REQUEST_METHOD']==='POST'?isset($_POST['configurator_enabled']):($edit['id']?product_configurator_enabled((int)$edit['id']):false);
?>
<section class="package-config" data-package-module-bindings><h3>Module aus der zentralen Verwaltung</h3><input type="hidden" name="module_bindings_present" value="1"><label class="checkbox-field"><input type="checkbox" name="configurator_enabled" value="1" <?= $configEnabled?'checked':'' ?> data-package-configurator><span>Als Paket-Konfigurator anbieten: Kunden wählen ihre Zusatzmodule selbst.</span></label><p class="small muted">Feste Pakete und individuelle Konfiguratoren können kostenpflichtige Zusatzmodule anbieten. Pro Modul wählst du „enthalten“ oder „vom Kunden wählbar“. Kostenlose Module sind immer fest enthalten. Die angezeigten Modulpreise kommen aus der zentralen Verwaltung.</p>
<?php foreach(['hosting'=>'Webhosting','server'=>'VPS'] as $moduleCategory=>$caption):$categoryModules=array_values(array_filter($catalogRows,fn($m)=>$m['category']===$moduleCategory)); ?>
<fieldset data-package-module-category="<?= $moduleCategory ?>" <?= $category!==$moduleCategory?'hidden':'' ?>><legend><?= $caption ?>-Module</legend>
<?php if(!$categoryModules): ?><p>Noch keine zentralen Module für diese Kategorie angelegt. <a class="text-link" href="/admin/module?kategorie=<?= $moduleCategory ?>" target="_blank" rel="noopener">Module verwalten <?= icon('arrow') ?></a></p><?php endif ?>
<?php foreach($categoryModules as $m):$b=$bindings[(int)$m['id']]??null;$posted=$_POST['package_modules'][$m['id']]??null;$selected=$posted?isset($posted['enabled']):($b && $b['active']);$mode=module_is_free($m)?'included':($posted['mode']??$b['mode']??'optional');$qty=$posted['included_qty']??$b['included_qty']??($m['control']==='select'?$m['default_qty']:1);if(!$posted && module_is_free($m))$qty=module_included_quantity($m+['_mode'=>$b['mode']??'optional','_included_qty'=>(int)$qty],$profile??[]); ?>
<article class="panel module-binding"><label class="checkbox-field"><input type="checkbox" name="package_modules[<?= (int)$m['id'] ?>][enabled]" value="1" <?= $selected?'checked':'' ?>><span><strong><?= e($m['label']) ?></strong><?= !$m['active']?' · zentraler Entwurf':'' ?><?= module_is_free($m)?' · 0,00 € · immer inklusive':'' ?><small><?= e($m['description']) ?></small></span></label><p class="small muted"><?= $m['control']==='select'?'Preis je Auswahloption':money($m['net_cents']).' netto pro '.e($m['unit_label']?:'Einheit') ?></p>
<div class="form-grid"><label class="field" data-binding-customer-mode><span>Verwendung im Paket</span><select name="package_modules[<?= (int)$m['id'] ?>][mode]"><option value="included" <?= $mode==='included'?'selected':'' ?>>Im Grundpreis enthalten</option><option value="optional" <?= module_is_free($m)?'disabled':'' ?> <?= $mode==='optional'?'selected':'' ?>>Vom Kunden wählbar · zzgl. Modulpreis</option></select></label>
<label class="field"><span><?= $m['control']==='select'?'Enthaltene Auswahl':'Enthaltene Menge' ?></span><?php if($m['control']==='select'): ?><select name="package_modules[<?= (int)$m['id'] ?>][included_qty]"><option value="0">Bitte auswählen</option><?php foreach(catalog_module_options($m) as $optionId=>$option): ?><option value="<?= (int)$optionId ?>" <?= (int)$qty===(int)$optionId?'selected':'' ?>><?= e($option['label']) ?></option><?php endforeach ?></select><?php else: ?><input type="number" name="package_modules[<?= (int)$m['id'] ?>][included_qty]" min="1" <?= (int)$m['max_qty']>0?'max="'.(int)$m['max_qty'].'"':'' ?> value="<?= (int)$qty ?>"><?php endif ?><small>Wird verwendet, wenn das Modul fest im Paket enthalten ist.</small></label></div><a class="text-link" href="/admin/module?id=<?= (int)$m['id'] ?>" target="_blank" rel="noopener">Modul und Preise zentral bearbeiten</a></article>
<?php endforeach ?></fieldset><?php endforeach ?></section>
